def as_floats(v):
    """Normalize a grid value into a list of floats.

    Accepts a scalar, a list of floats, a list of training records, or a dict
    of any of these (e.g. {seed: record}).
    """
    if isinstance(v, dict):
        return as_floats(list(v.values()))
    if isinstance(v, (int, float)):
        return [float(v)]
    out = []
    for r in v:
        if isinstance(r, (int, float)):
            out.append(float(r))
        elif isinstance(r, dict) and "accuracy_pct" in r:
            out.append(float(r["accuracy_pct"]))
        else:
            raise TypeError(f"cannot interpret {r!r} as an accuracy value")
    return out


