def _write_metrics(payload):
    """Atomically write results/metrics.json.

    save-as-you-go: every claim that has been computed is on disk before the
    next one starts, so a late failure cannot lose an earlier result.
    """
    os.makedirs(config.RESULT_DIR, exist_ok=True)
    path = os.path.join(config.RESULT_DIR, "metrics.json")
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(payload, f, indent=2)
    os.replace(tmp, path)
    log(f"[write] {path}")
    return path

